Algorithm Promedio
  Define nota As Integer;
  Define suma As Integer <- 0;
  Define cantidad As Integer <- 0;
  Read nota;
  While nota <> -1 Do
    suma <- suma + nota;
    cantidad <- cantidad + 1;
    Read nota;
  EndWhile
  If cantidad = 0 Then
    Write "No hay notas";
  Else
    Write suma / cantidad;
  EndIf
EndAlgorithm
